VID.narration = {"look":{"bar":false},"scenes":[{"dur":7.616,"caps":[[0.5,7.07,"Lecture six. Genetic programming. This is how evolution can write a program for you."]],"warp":[[0,0],[0.5,0.9],[7.616,4]]},{"dur":18.344,"caps":[[0.5,6.75,"Normally you write the program."],[7,12.13,"In GP you give examples of what it should do..."],[12.38,16.95,"...and evolution finds a program that matches."]],"warp":[[0,0],[0.5,0.4],[7,3.5],[12.38,6.3],[18.344,9]]},{"dur":23.336,"caps":[[0.5,6.67,"A program can be drawn as a tree."],[6.92,13.81,"It runs from the leaves up to the root."],[14.06,21.59,"Change the input and a different branch is used."]],"warp":[[0,0],[0.5,0.4],[6.92,4],[14.06,9],[23.336,14]]},{"dur":25.101,"caps":[[0.5,9.71,"Build programs from two sets: functions and terminals."],[9.96,15.49,"Grow downwards, picking parts at random."],[15.74,23.91,"At the limit, only terminals."]],"warp":[[0,0],[0.5,0.4],[9.96,4],[15.74,9.5],[25.101,14]]},{"dur":26.796,"caps":[[0.5,9.55,"Run the program on many inputs."],[9.8,17.49,"Error = the area between its curve and the target."],[17.74,25.43,"Lower error means a fitter program."]],"warp":[[0,0],[0.5,0.4],[9.8,4.5],[17.74,9.3],[26.796,13.5]]},{"dur":19.783,"caps":[[0.5,6.99,"Pick a node at random."],[7.24,10.85,"Cut off its subtree."],[11.1,17.99,"Grow a new random subtree in its place."]],"warp":[[0,0],[0.5,0.4],[7.24,3.5],[11.1,6.3],[19.783,11]]},{"dur":23.313,"caps":[[0.5,7.39,"Pick a point in each parent."],[7.64,12.85,"Swap the two subtrees."],[13.1,22.23,"Same nodes, but the children have new sizes."]],"warp":[[0,0],[0.5,0.4],[7.64,3.5],[13.1,7.3],[23.313,12]]},{"dur":21.687,"caps":[[0.5,6.99,"Four random programs. Lower error is better."],[7.24,13.25,"Next generation: a copy, a mutant, two children."],[13.5,20.95,"A few generations later: x² + x + 1."]],"warp":[[0,0],[0.5,0.4],[7.24,4.8],[13.5,10.7],[21.687,17]]},{"dur":23.336,"caps":[[0.5,10.11,"Five things to choose before a run."],[10.36,16.53,"Only + and −? Straight lines only."],[16.78,21.43,"Add × and the curve fits."]],"warp":[[0,0],[0.5,0.4],[10.36,7.5],[16.78,10.4],[23.336,13]]},{"dur":16.765,"caps":[],"warp":[[0,0],[0.605,1.1],[2.625,2.2],[6.085,3.3],[10.585,4.4],[16.765,9]]}]};
